// L10n.text / L10n.format from CharkerCore. Keys are the Chinese source
// strings, exactly as the macOS app writes them; English comes from the macOS
// app's own tables (l10n/en.json, generated by tools/l10n) plus the handful of
// strings only the Windows app has (l10n/windows/*.json).

// English for strings only the Windows app has, one table per page.
const WINDOWS_TABLES = ['shell', 'overview', 'energy', 'devices', 'menubar', 'advanced', 'about'];

let locale = 'zh';
let table = {};

export async function loadLocale(next) {
  locale = next === 'en' ? 'en' : 'zh';
  document.documentElement.lang = locale === 'en' ? 'en' : 'zh-CN';
  if (locale !== 'en' || Object.keys(table).length) return;
  const load = (path) =>
    fetch(path)
      .then((r) => (r.ok ? r.json() : {}))
      .catch(() => ({}));
  const tables = await Promise.all([
    load('/l10n/en.json'),
    ...WINDOWS_TABLES.map((name) => load(`/l10n/windows/${name}.json`)),
  ]);
  table = Object.assign({}, ...tables);
}

export function currentLocale() {
  return locale;
}

/** L10n.text */
export function t(key) {
  if (locale !== 'en') return key;
  return table[key] ?? key;
}

/** L10n.format: printf with %@ %d %ld %f %.Nf %% and positional %1$@. */
export function tf(key, ...args) {
  return format(t(key), args);
}

export function format(pattern, args) {
  let next = 0;
  return pattern.replace(/%(?:(\d+)\$)?(\.(\d+))?(l{0,2}d|@|f|%|s|u)/g, (m, pos, _p, prec, kind) => {
    if (kind === '%') return '%';
    const value = pos ? args[Number(pos) - 1] : args[next++];
    switch (kind) {
      case 'f':
        return Number(value ?? 0).toFixed(prec === undefined ? 6 : Number(prec));
      case 'd':
      case 'ld':
      case 'lld':
      case 'u':
        return String(Math.trunc(Number(value ?? 0)));
      default:
        return String(value ?? '');
    }
  });
}
